         LINERD = LINERD + 1
         IF(IEOF.EQ.1) THEN
            IF(MASWRK) WRITE(IW,'(1X,A/)')
     *      'ERROR: END OF FILE LOOKING FOR $QUANPO GROUP.'
            CALL ABRT
         END IF
         TEXT='        '
         LGSTR=-8
         CALL GSTRNG(TEXT,LGSTR)
         IF(TEXT.NE.'$QUANPO ') GOTO 90
      END IF
