                  NLIST(3,KDIHB) = LISTB2A(NORDERB(LISTAB(II3)))
                  NLIST(4,KDIHB) = LISTB2A(NORDERB(LISTAB(II4)))
                  DIHB0 (KDIHB)  = DIHB0 (IDIHB)
                  FCDIHB(KDIHB)  = FCDIHB(IDIHB)
               END IF
            ENDDO
            NDIHB = KDIHB
C
            KDIHB = 0
            DO IDIHB =1, N2DIHB
               II1 = NLISTB(1,IDIHB)
               II2 = NLISTB(2,IDIHB)
               II3 = NLISTB(3,IDIHB)
               II4 = NLISTB(4,IDIHB)
