               IF(NORDERB(II1).GT.0.AND.NORDERB(II2).GT.0.AND.
     *            NORDERB(II3).GT.0.AND.NORDERB(II4).LE.0.AND.
     *            LISTAB(NFFATSV+II4).GT.0                   ) THEN
                  KDIHB = KDIHB + 1
                  NLISTB(1,KDIHB) = LISTB2A(NORDERB(II1))
