               II4 = NLISTB(4,IDIHB)
               DO JDIHB =1, NDIHB
                  JJ1 = NLIST(1,JDIHB)
                  JJ2 = NLIST(2,JDIHB)
                  JJ3 = NLIST(3,JDIHB)
                  JJ4 = NLIST(4,JDIHB)
                  IF((II1.EQ.JJ1.AND.II2.EQ.JJ2.AND.
     *                II3.EQ.JJ3.AND.II4.EQ.JJ4).OR.
     *               (II1.EQ.JJ4.AND.II2.EQ.JJ3.AND.
