                      DIHB0 (JDIHB)  = PT5*(DIHB0 (JDIHB) +
     *                                      DIHB0B(IDIHB))
                      FCDIHB(JDIHB)  = PT5*(FCDIHB(JDIHB) +
     *                                      FCDIHBB(IDIHB))
                      GOTO 273
                  END IF
               ENDDO
               KDIHB = KDIHB + 1
               NLIST(1,KDIHB) = II1
               NLIST(2,KDIHB) = II2
               NLIST(3,KDIHB) = II3
               NLIST(4,KDIHB) = II4
               DIHB0(KDIHB)   = DIHB0B(IDIHB)
               FCDIHB(KDIHB)  = FCDIHBB(IDIHB)
 273           CONTINUE
            ENDDO
