                  NLIST(4,IDIHB) = IZ5G9
                  IZ5G9          = NLIST(2,IDIHB)
                  NLIST(2,IDIHB) = NLIST(3,IDIHB)
                  NLIST(3,IDIHB) = IZ5G9
